#include <stdio.h>

int main(void) {
    char digits[101];
    // 按字符串读取领取码，前导零必须保留它的位置。
    scanf("%100s", digits);
    int sum = 0;
    for (int i = 0; digits[i] != '\0'; i++) {
        // 程序下标从0开始，偶数下标对应题目奇数位置，乘1。
        int weight = i % 2 == 0 ? 1 : 3;
        sum += (digits[i] - '0') * weight;
    }
    // 先补足个位余数，再取模，让原本整除10时的校验位为0。
    printf("%d\n", (10 - sum % 10) % 10);
    return 0;
}

